def transform(grid):
    out=[r[:] for r in grid]
    for i,r in enumerate(grid):
        nz=[j for j,x in enumerate(r) if x]
        if len(nz)==2:
            a,b=nz
            if (r[a],r[b]) in [(1,8),(8,1),(7,4),(4,7)] and b-a>1:
                out[i][a+1]=r[b]
                out[i][b]=0
    return out
